n = int(input())
A = list(map(int, input().split()))
count = 0
positions = {}

for i in range(2 * n):
    if A[i] not in positions:
        positions[A[i]] = []
    positions[A[i]].append(i)

for color in positions:
    if len(positions[color]) == 2 and positions[color][1] - positions[color][0] == 2:
        count += 1

print(count)
